/// <summary>
/// Test seam for TEST_MD31RegressionTest. Exposes SJPMDItemMasterImportService.assignProcessingGroups,
/// which orchestrate only runs before it creates batch tasks, so a test can check the split
/// without a batch job. The method under test runs unchanged.
/// </summary>
public final class TEST_MD31GroupAssigningService extends SJPMDItemMasterImportService
{
    boolean countFails;
}

Method.Source:
public static TEST_MD31GroupAssigningService construct()
{
    return new TEST_MD31GroupAssigningService();
}

/// <summary>
/// Runs assignProcessingGroups in its own transaction, as orchestrate does.
/// </summary>
public void assign(int _numOfThreads, Filename _fileName)
{
    ttsbegin;
    this.assignProcessingGroups(_numOfThreads, _fileName);
    ttscommit;
}

/// <summary>
/// countNewRows, the first query orchestrate runs after taking the run lock, throws an
/// error, as a failing SQL statement would.
/// </summary>
public void failCountNewRows()
{
    countFails = true;
}

protected int64 countNewRows(str _fileName)
{
    if (countFails)
    {
        throw error('TEST: countNewRows fault');
    }

    return super(_fileName);
}
